public class ConditionalsDemo {
    public static void main(String[] args) {
        int score = 85;
        if (score >= 90) {
            System.out.println("Grade A");
        } else if (score >= 80) {
            System.out.println("Grade B");
        } else {
            System.out.println("Grade C");
        }

        String day = "MONDAY";
        switch (day) {
            case "MONDAY" -> System.out.println("Start of work week");
