import java.util.Scanner;

public class Calculator {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter expression (e.g., 5 + 3): ");
        if (!scanner.hasNextDouble()) return;
        double num1 = scanner.nextDouble();
        char op = scanner.next().charAt(0);
        double num2 = scanner.nextDouble();

        double result = switch (op) {
            case '+' -> num1 + num2;
            case '-' -> num1 - num2;
            case '*' -> num1 * num2;
            case '/' -> num2 != 0 ? num1 / num2 : Double.NaN;
            default -> Double.NaN;
        };
        System.out.println("Result: " + result);
        scanner.close();
    }
}

import java.util.Scanner;
import java.util.Random;

public class GuessingGame {
    public static void main(String[] args) {
        int target = new Random().nextInt(100) + 1;
        Scanner scanner = new Scanner(System.in);
        int guess = 0, attempts = 0;
        while (guess != target) {
            System.out.print("Guess a number (1-100): ");
            guess = scanner.nextInt();
            attempts++;
            if (guess < target) System.out.println("Too low!");
            else if (guess > target) System.out.println("Too high!");
        }
        System.out.println("Correct! Took " + attempts + " attempts.");
        scanner.close();
    }
}

public class PalindromeChecker {
    public static boolean isPalindrome(String input) {
        String cleaned = input.replaceAll("[^a-zA-Z0-9]", "").toLowerCase();
        int left = 0, right = cleaned.length() - 1;
        while (left < right) {
            if (cleaned.charAt(left) != cleaned.charAt(right)) return false;
            left++;
            right--;
        }
        return true;
    }
    public static void main(String[] args) {
        System.out.println(isPalindrome("A man, a plan, a canal: Panama")); // true
    }
}

public class PrimeChecker {
    public static boolean isPrime(int n) {
        if (n <= 1) return false;
        if (n <= 3) return true;
        if (n % 2 == 0 || n % 3 == 0) return false;
        for (int i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) return false;
        }
        return true;
    }
    public static void main(String[] args) {
        System.out.println("Is 29 prime? " + isPrime(29));
    }
}

import java.util.Arrays;

public class ArrayOps {
    public static void reverse(int[] arr) {
        int i = 0, j = arr.length - 1;
        while (i < j) {
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
            i++; j--;
        }
    }
    public static void main(String[] args) {
        int[] data = {10, 20, 30, 40, 50};
        reverse(data);
        System.out.println(Arrays.toString(data)); // [50, 40, 30, 20, 10]
    }
}

public class AnagramChecker {
    public static boolean isAnagram(String s1, String s2) {
        if (s1.length() != s2.length()) return false;
        int[] counts = new int[256];
        for (int i = 0; i < s1.length(); i++) {
            counts[s1.charAt(i)]++;
            counts[s2.charAt(i)]--;
        }
        for (int count : counts) {
            if (count != 0) return false;
        }
        return true;
    }
    public static void main(String[] args) {
        System.out.println(isAnagram("listen", "silent")); // true
    }
}
